-- Reviewed offline; never applied automatically.
BEGIN;
CREATE EXTENSION IF NOT EXISTS unaccent WITH SCHEMA extensions;
CREATE TABLE public.organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id),display_name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.organization_members(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations,user_id uuid NOT NULL REFERENCES public.profiles,role text NOT NULL CHECK(role IN ('owner','admin','member')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,user_id));
CREATE FUNCTION public.active_org() RETURNS uuid LANGUAGE sql STABLE SET search_path='' AS $$ SELECT nullif(current_setting('app.organization_id',true),'')::uuid $$;
CREATE FUNCTION public.is_member(org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.organization_members WHERE organization_id=org AND user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_member(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_member(uuid) TO authenticated;
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.organization_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_read ON public.organizations FOR SELECT TO authenticated USING(public.is_member(id));
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR EXISTS(SELECT 1 FROM public.organization_members a JOIN public.organization_members b USING(organization_id) WHERE a.user_id=auth.uid() AND b.user_id=profiles.id));
CREATE POLICY member_read ON public.organization_members FOR SELECT TO authenticated USING(public.is_member(organization_id));
GRANT SELECT ON public.organizations,public.profiles,public.organization_members TO authenticated;
-- Membership management is deliberately not granted to clients. Operators provision via SQL after an Auth invitation.
INSERT INTO public.organizations(name,slug) VALUES('Loung Tech','loung-tech') ON CONFLICT(slug) DO NOTHING;
CREATE TABLE public.leads(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,organization_id uuid NOT NULL DEFAULT public.active_org() REFERENCES public.organizations(id),"empresa" text,"cidade" text,"segmento" text,"telefone" text,"whatsapp" text,"email" text,"site" text,"endereco" text,"avaliacao" text,"quantidade_avaliacoes" integer,"google_maps" text,"qualification_status" text,"qualification_score" integer,"opportunity" text,"qualification_reasons" text,"qualification_evidence" text,"qualification_limitations" text,"rules_version" text,"analyzed_at" text,"responsavel" text,"status" text,"observacoes" text,"provider" text,"provider_place_id" text,"ultimo_contato" text,"proximo_contato" text,"proxima_acao" text,"canal_preferencial" text,"whatsapp_consent" text,"consent_source" text,"consent_at" text,"consent_number" text,"do_not_contact" integer,"created_at" text,"updated_at" text,created_by uuid REFERENCES public.profiles(id), updated_by uuid REFERENCES public.profiles(id),UNIQUE(organization_id,id),CHECK(length(trim(empresa))>0),CHECK(status IS NOT NULL));
ALTER TABLE public.leads ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.leads FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_read ON public.leads FOR SELECT TO authenticated USING(public.is_member(organization_id) AND organization_id=public.active_org());
GRANT SELECT ON public.leads TO authenticated;
CREATE TABLE public.lead_interactions(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,organization_id uuid NOT NULL DEFAULT public.active_org() REFERENCES public.organizations(id),lead_id bigint NOT NULL,tipo text NOT NULL,canal text,descricao text,created_at text NOT NULL,created_by uuid REFERENCES public.profiles(id), updated_by uuid REFERENCES public.profiles(id),FOREIGN KEY(organization_id,lead_id) REFERENCES public.leads(organization_id,id));
ALTER TABLE public.lead_interactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lead_interactions FORCE ROW LEVEL SECURITY;
