GRANT SELECT ON public.lead_interactions TO authenticated;
CREATE INDEX ON public.lead_interactions(organization_id,lead_id);
CREATE TABLE public.outreach(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,organization_id uuid NOT NULL DEFAULT public.active_org() REFERENCES public.organizations(id),lead_id bigint NOT NULL,canal text NOT NULL DEFAULT 'whatsapp',mensagem text NOT NULL,angulo text,confianca double precision,status text NOT NULL CHECK(status IN ('GERADA','EDITADA','APROVADA','ENVIADA','RESPONDEU','CANCELADA')),criado_em text NOT NULL,atualizado_em text NOT NULL,aprovado_em text,enviado_em text,respondeu_em text,provider text,model text,revisado_em text,created_by uuid REFERENCES public.profiles(id), updated_by uuid REFERENCES public.profiles(id),UNIQUE(organization_id,id,lead_id),FOREIGN KEY(organization_id,lead_id) REFERENCES public.leads(organization_id,id));
ALTER TABLE public.outreach ENABLE ROW LEVEL SECURITY;
