CREATE FUNCTION public.stamp_actor() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF TG_OP='INSERT' THEN NEW.created_by:=auth.uid(); ELSE NEW.created_by:=OLD.created_by; END IF;
 NEW.updated_by:=auth.uid(); RETURN NEW;
END $$;
CREATE FUNCTION public.audit_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE oldj jsonb; newj jsonb; lid bigint;
BEGIN
 IF TG_OP='UPDATE' THEN oldj:=to_jsonb(OLD); END IF;
 newj:=to_jsonb(NEW);
 IF TG_TABLE_NAME='leads' THEN
   SELECT jsonb_object_agg(key,value) INTO newj FROM jsonb_each(newj) WHERE key IN ('id','status','observacoes','ultimo_contato','proximo_contato','proxima_acao','updated_at','provider','provider_place_id');
   IF oldj IS NOT NULL THEN SELECT jsonb_object_agg(key,value) INTO oldj FROM jsonb_each(oldj) WHERE key IN ('id','status','observacoes','ultimo_contato','proximo_contato','proxima_acao','updated_at','provider','provider_place_id'); END IF;
 ELSE
   newj:=newj-'payload'-'value'; oldj:=oldj-'payload'-'value';
 END IF;
 lid:=CASE WHEN TG_TABLE_NAME='leads' THEN (newj->>'id')::bigint ELSE (newj->>'lead_id')::bigint END;
 INSERT INTO public.audit_events(organization_id,lead_id,actor_id,action,old_value,new_value,origin)
 VALUES(NEW.organization_id,lid,auth.uid(),TG_TABLE_NAME||'.'||lower(TG_OP),oldj,newj,CASE WHEN auth.uid() IS NULL THEN 'migration' ELSE 'web' END);
 RETURN NEW;
END $$;
CREATE UNIQUE INDEX leads_place ON public.leads(organization_id,provider,provider_place_id) WHERE nullif(trim(provider),'') IS NOT NULL AND nullif(trim(provider_place_id),'') IS NOT NULL;
CREATE INDEX leads_stage ON public.leads(organization_id,status);
CREATE INDEX leads_followup ON public.leads(organization_id,proximo_contato);
CREATE FUNCTION public.fold(v text) RETURNS text LANGUAGE sql STABLE SET search_path='' AS $$ SELECT regexp_replace(lower(extensions.unaccent(coalesce(v,''))), '[^a-z0-9]', '', 'g') $$;
CREATE FUNCTION public.instr(v text,needle text) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT strpos(v,needle) $$;
CREATE FUNCTION public.julianday(v text) RETURNS double precision LANGUAGE plpgsql STABLE AS $$ BEGIN RETURN extract(epoch FROM v::timestamptz)::double precision; EXCEPTION WHEN OTHERS THEN RETURN NULL; END $$;
CREATE FUNCTION public.commercial_status(v text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE v WHEN 'Novo Lead' THEN 'Novo' WHEN 'Mensagem gerada' THEN 'Novo' WHEN 'Revisado' THEN 'Novo' WHEN 'Contatado' THEN 'Contato realizado' WHEN 'Respondeu' THEN 'Em conversa' WHEN 'Reunião' THEN 'Reunião agendada' WHEN 'Reunião marcada' THEN 'Reunião agendada' WHEN 'Não interessado' THEN 'Sem interesse' ELSE v END $$;
CREATE TRIGGER stamp BEFORE INSERT OR UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.stamp_actor();
