-- Create a dedicated login externally; never use postgres/service_role for runtime.
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='loung_api') THEN CREATE ROLE loung_api NOLOGIN NOINHERIT NOBYPASSRLS; END IF; END $$;
